import numpy as np, os, time
from math import sqrt
try:
    from scipy.optimize import linprog
    from scipy.optimize import minimize
    SCIPY_AVAILABLE = True
except Exception:
    SCIPY_AVAILABLE = False

N = 32
SHRINK = 1.0 - 1e-12
IMPROVE_EPS = 1e-8
SLACK_REQ = 1e-10

# ---------- Geometry / LP ----------
def _pairwise_distances(C: np.ndarray) -> np.ndarray:
    diff = C[:, None, :] - C[None, :, :]
    d2 = np.sum(diff * diff, axis=-1)
    np.fill_diagonal(d2, 0.0)
    d = np.sqrt(d2, out=np.zeros_like(d2), where=(d2 > 0))
    return d

def _boundary_margins(C: np.ndarray) -> np.ndarray:
    x = C[:, 0]; y = C[:, 1]
    return np.minimum(np.minimum(x, 1.0 - x), np.minimum(y, 1.0 - y))

def _solve_lp_for_radii(C: np.ndarray):
    n = C.shape[0]
    b = _boundary_margins(C)
    if not SCIPY_AVAILABLE:
        r = 0.75 * np.minimum(b, np.median(b))
        r = np.maximum(r, 1e-12)
        return r, float(np.sum(r)), True
    D = _pairwise_distances(C)
    rows, rhs = [], []
    for i in range(n):
        for j in range(i + 1, n):
            row = np.zeros(n, dtype=float); row[i] = 1.0; row[j] = 1.0
            rows.append(row); rhs.append(D[i, j])
    A_ub = np.vstack(rows) if rows else None
    b_ub = np.array(rhs, dtype=float) if rows else None
    c = -np.ones(n, dtype=float)
    bounds = [(0.0, float(max(0.0, bi))) for bi in b]
    res = linprog(c, A_ub=A_ub, b_ub=b_ub, bounds=bounds, method="highs")
    if not res.success:
        return np.zeros(n, dtype=float), 0.0, False
    r = res.x.astype(float)
    return r, float(-res.fun), True

def _min_slack(C: np.ndarray, r: np.ndarray) -> float:
    x = C[:, 0]; y = C[:, 1]
    sl = np.min(x - r)
    sr = np.min((1.0 - x) - r)
    sd = np.min(y - r)
    su = np.min((1.0 - y) - r)
    D = _pairwise_distances(C)
    Rsum = r[:, None] + r[None, :]
    np.fill_diagonal(D, np.inf)
    pair_sl = np.min(D - Rsum)
    return float(min(sl, sr, sd, su, pair_sl))

def _clip(C: np.ndarray, eps: float = 1e-6) -> np.ndarray:
    return np.clip(C, eps, 1.0 - eps)

# ---------- Seeds ----------
def _load_artifact():
    try:
        data = np.load('storage/verity/sumr32_best.npz')
        C = data['centers']; r = data['radii']; obj = float(data.get('obj', np.sum(r)))
        if C.shape == (N, 2) and r.shape == (N,):
            return C.copy(), r.copy(), obj
    except Exception:
        pass
    return None

def _grid_minus_corners():
    s = 1.0 / 6.0
    r0 = 0.5 * s
    xs = r0 + s * np.arange(6, dtype=float)
    ys = r0 + s * np.arange(6, dtype=float)
    centers = []
    for i in range(6):
        for j in range(6):
            if (i == 0 and j == 0) or (i == 0 and j == 5) or (i == 5 and j == 0) or (i == 5 and j == 5):
                continue
            centers.append([xs[j], ys[i]])
    return np.array(centers, dtype=float)

def _grid_noise_seed(noise: float = 0.04, seed: int = 0) -> np.ndarray:
    rng = np.random.default_rng(seed)
    C = _grid_minus_corners()
    C = C + rng.uniform(-noise, noise, size=C.shape)
    return _clip(C, 0.05)

def _row_phase_seed(phase: float = 0.02, ymarg: float = 0.11) -> np.ndarray:
    counts = [5,4,5,4,5,4,5]
    ys = np.linspace(ymarg, 1.0 - ymarg, len(counts))
    centers = []
    for rid, k in enumerate(counts):
        m = 0.08
        xs = np.linspace(m, 1.0 - m, k) if k > 1 else np.array([0.5], float)
        if k == 4:
            xs = np.clip(xs + phase, m, 1.0 - m)
        for x in xs:
            centers.append([x, ys[rid]])
    return _clip(np.array(centers, dtype=float), 0.05)

def _farthest_sampling(margin=0.02, candidates=600, seed=0) -> np.ndarray:
    rng = np.random.default_rng(seed)
    pts = [np.array([0.5, 0.5], dtype=float)]
    for _ in range(1, N):
        cand = rng.uniform(margin, 1.0 - margin, size=(candidates, 2))
        exist = np.array(pts, dtype=float)
        d = np.sqrt(np.sum((cand[:, None, :] - exist[None, :, :])**2, axis=-1))
        min_to_pts = np.min(d, axis=1)
        b = np.minimum(np.minimum(cand[:, 0], 1.0 - cand[:, 0]), np.minimum(cand[:, 1], 1.0 - cand[:, 1]))
        score = np.minimum(min_to_pts, 2.0 * b)
        pts.append(cand[int(np.argmax(score))])
    return _clip(np.array(pts, dtype=float), 0.05)

# ---------- SLSQP joint stage ----------
def _obj_slsqp(x):
    return -np.sum(x[2::3])

def _cons_slsqp(x):
    n = N
    C = np.stack([x[0::3], x[1::3]], axis=1)
    r = x[2::3]
    diff = C[:, None, :] - C[None, :, :]
    D2 = np.sum(diff * diff, axis=-1)
    I, J = np.triu_indices(n, 1)
    g_pairs = D2[I, J] - (r[I] + r[J])**2
    g_b = np.empty(n * 4, dtype=float)
    g_b[0::4] = C[:, 0] - r
    g_b[1::4] = (1.0 - C[:, 0]) - r
    g_b[2::4] = C[:, 1] - r
    g_b[3::4] = (1.0 - C[:, 1]) - r
    return np.concatenate([g_pairs, g_b])

def _run_slsqp_from_centers(C0: np.ndarray, r_init: float, maxiter: int, ftol: float):
    x0 = np.empty(N * 3, dtype=float)
    x0[0::3] = C0[:, 0]
    x0[1::3] = C0[:, 1]
    x0[2::3] = np.full(N, r_init, dtype=float)
    bounds = [(1e-6, 1.0 - 1e-6), (1e-6, 1.0 - 1e-6), (1e-12, 0.5)] * N
    con = {'type': 'ineq', 'fun': _cons_slsqp}
    if SCIPY_AVAILABLE:
        res = minimize(_obj_slsqp, x0, method='SLSQP', bounds=bounds, constraints=con,
                       options={'maxiter': int(max(30, maxiter)), 'ftol': float(ftol), 'disp': False})
        C = np.stack([res.x[0::3], res.x[1::3]], axis=1)
        r = res.x[2::3]
        return _clip(C, 1e-6), np.maximum(r, 1e-12), bool(res.success)
    else:
        return _clip(C0, 1e-6), np.full(N, r_init, dtype=float), False

# ---------- Return path (immutable) ----------
def _fallback():
    C = _grid_minus_corners()
    r = np.full(N, (1.0/12.0) * SHRINK, dtype=float)
    return C, r

def _return_loader():
    try:
        data = np.load('storage/verity/sumr32_best.npz')
        C = data['centers']; r = data['radii']
        if C.shape == (N, 2) and r.shape == (N,):
            return C.astype(float), np.maximum(r * SHRINK, 1e-16).astype(float)
    except Exception:
        pass
    return _fallback()

# ---------- Persist if improved (slack on micro-shrunk radii) ----------
def _persist_if_improved(Cbest, rbest, objbest, obj0):
    if objbest > obj0 + IMPROVE_EPS:
        r_safe = rbest * SHRINK
        if _min_slack(Cbest, r_safe) >= SLACK_REQ:
            try:
                os.makedirs('storage/verity', exist_ok=True)
                # Persist un-shrunk radii (maximize ∑r); loader will micro-shrink on return
                np.savez('storage/verity/sumr32_best.npz', centers=Cbest, radii=rbest, obj=float(np.sum(rbest)))
            except Exception:
                pass

# ---------- Main ----------
def construct_packing() -> tuple:
    # Two-stage offline search; immutable return via loader v4
    total_budget = 1180.0  # seconds (≤20 min)
    t0 = time.time()

    art = _load_artifact()
    if art is not None:
        baseC, baseR, baseObj = art
    else:
        baseC, baseR, baseObj = None, None, -1.0

    bestC = baseC.copy() if baseC is not None else None
    bestR = baseR.copy() if baseR is not None else None
    bestObj = float(baseObj)

    # Stage 1: 32 starts (breadth) — 16 grid-noise, 8 row-phase, 8 farthest
    starts = []
    for k in range(16):
        starts.append(_grid_noise_seed(noise=0.04, seed=1000 + k))
    for k in range(8):
        starts.append(_row_phase_seed(phase=0.02, ymarg=0.11))
    for k in range(8):
        starts.append(_farthest_sampling(margin=0.02, candidates=600, seed=2000 + k))

    time_limit_stage1 = total_budget * 0.8
    for C0 in starts:
        if time.time() - t0 > time_limit_stage1:
            break
        C1, r1, ok = _run_slsqp_from_centers(C0, r_init=0.05, maxiter=125, ftol=1e-10)
        # LP finalize on SLSQP result
        r_lp, obj_lp, ok_lp = _solve_lp_for_radii(C1)
        if ok_lp and obj_lp > bestObj + 1e-12:
            bestC, bestR, bestObj = C1.copy(), r_lp.copy(), obj_lp

    # Stage 2: depth on best start (if any), 500 iters, then LP finalize
    if bestC is not None and (time.time() - t0) < total_budget:
        C2, r2, ok2 = _run_slsqp_from_centers(bestC, r_init=0.05, maxiter=500, ftol=1e-12)
        r2_lp, obj2_lp, ok2_lp = _solve_lp_for_radii(C2)
        if ok2_lp and obj2_lp > bestObj + 1e-12:
            bestC, bestR, bestObj = C2.copy(), r2_lp.copy(), obj2_lp

    # Persist only if safely improved (slack checked on micro-shrunk radii)
    if art is not None:
        _persist_if_improved(bestC, bestR, bestObj, baseObj)
    else:
        _persist_if_improved(bestC, bestR, bestObj, -1.0)

    # Immutable return path: loader v4 (centers unchanged; radii × (1−1e−12))
    return _return_loader()
